request.prompt:
You are operating on a local file. You may make this change yourself.

A tool is available to you:

  edit_file(path, contents)   replaces the whole file at `path` with `contents`

The file is index.html and its current contents are:

<!DOCTYPE html>
<html>
<head><title>s08</title><style>.gone{display:none}</style></head>
<body>
<h2>s08</h2>
<input type="text" id="text">
<ul id="parts">
  <li class="item">washer</li>
  <li class="item">wrench</li>
  <li class="item">anvil</li>
  <li class="item">bolt</li>
  <li class="item">clamp</li>
</ul>
<script>
const model = { query: '' };
const field = document.getElementById('text');
const rows = Array.from(document.querySelectorAll('#parts .item'));
function narrowList() {
  model.query = field.value.toLowerCase();
  const q = model.query;
  rows.forEach(function (el) {
    const hit = el.textContent.toLowerCase().indexOf(q) !== -1;
    el.className = hit ? 'item' : 'item gone';
  });
}
field.addEventListener('input', narrowList);
</script>
</body>
</html>


Make this change: when #clear-filter is clicked: #text is empty; every item in the list is visible again. Ensure typing in the filter still narrows the list.
Everything the page already does must keep working.

Call the tool. Reply with exactly one call, in this form and nothing else:

edit_file("index.html", `<!DOCTYPE html>
...the complete updated page...
</html>`)

